 * > count(vector<int>{1, 2, 3, 4, 4, 5}, 4)
 * 2
 * > count(vector<int>{1, 2, 3, 4}, 8)
 * 0
 * > count(vector<int>{1, 1, 2, 3, 3, 2, 2}, 2)
 * 3
 */
int count(vector<int> nums, int target) {
	int count = 0;
	for (int i = 0; i < nums.size(); ++i)
		if (nums[i] == target)
			count++;
	return count;
}

/**
 * Write a function to search for a given element in an array of integers, using binary search.
 * > binarySearch(vector<int>{1, 2, 3, 4, 5, 6}, 4)
 * 3
 * > binarySearch(vector<int>{1, 2, 3, 4, 5, 6}, 8)
 * -1
 * > binarySearch(vector<int>{1, 2, 3, 4, 5, 6}, 1)
 * 0
 */
int binarySearch(vector<int> nums, int target) {
	std::sort(nums.begin(), nums.end());
	int low = 0, high = nums.size() - 1;
	while (low <= high) {
		int mid = (low + high) / 2;
		if (nums[mid] == target)
			return mid;
		else if (nums[mid] < target)
			low = mid + 1;
		else
			high = mid - 1;
	}
	return -1;
}

