	int count = 0;
	for (int i = 0; i < s.size(); i++) {
		if (prev == s[i]) {
			count++;
			if (i >= s.size() - e.size()) {
				count = 0;
			}
		}
		else {
			prev = s[i];
			count = 1;
		}
	}
	return count;
}

