 * False
 * > isSorted([ 1, 2, 3, 4, 5 ])
 * True
 * > isSorted([ 1, 2, 3, 5, 4 ])
 * False
 */
bool isSorted(int* arr, int arrLength) {
	if(arrLength <= 1)
		return true;
	int i = 0;
	while(i < arrLength - 1) {
		if(arr[i] > arr[i + 1])
			return false;
		i++;
	}
	return true;
}

