bool isIncreasingOrder(vector<int> testArr) {
	for (int i = 0; i < testArr.size() - 1; i++) {
		if (testArr[i] > testArr[i + 1]) {
			return false;
		}
	}
	return true;
}

// Write a function to find if the given array is sorted in increasing order or not.
// This function can be written with recursion.
bool isIncreasingOrder2(vector<int> testArr, int currPos) {
	if (currPos >= testArr.size() - 1) {
		return true;
	}
	if (testArr[currPos] > testArr[currPos + 1]) {
		return false;
	}
	return isIncreasingOrder2(testArr, currPos + 1);
}

// Write a function to count the number of times each word occurred in a given sentence.
unordered_map<string, int> countWords(string testStr) {
	unordered_map<string, int> ans;
	string currWord;
	for (int i = 0; i < testStr.size(); i++) {
		if (testStr[i] == ' ') {
			currWord += testStr[i];
			ans[currWord]++;
			currWord = "";
		} else {
			currWord += testStr[i];
		}
	}
	currWord += testStr[testStr.size() - 1];
	ans[currWord]++;
	return ans;
}

