/**
 * Write a function to print the count of even and odd numbers from a list.
 * > count_even_odd([1, 2, 3, 4, 5, 6, 7, 8, 9])
 * Even count is 5 and Odd count is 4
 * > count_even_odd([1, 3, 5, 7, 9, 11, 13, 15, 17])
 * Even count is 8 and Odd count is 8
 * > count_even_odd([2, 4, 6, 8, 10, 12, 14, 16, 18])
 * Even count is 9 and Odd count is 9
 */
void count_even_odd(vector<int> list1) {
	int count_even = 0;
	int count_odd = 0;
	for (int i = 0; i < list1.size(); i++) {
		if (list1[i] % 2 == 0) {
			count_even++;
		}
		else {
			count_odd++;
		}
	}
	cout << "Even count is " << count_even << " and Odd count is " << count_odd << endl;
}


