 * > surfaceareaCylinder(4, 8)
 * 84
 * > surfaceareaCylinder(7, 8)
 * 840
 * > surfaceareaCylinder(7, 8, 2)
 * 840
 */
int surfaceareaCylinder(int radius, int height, int slices = 1) {
	return 2*pi*radius*radius*height + 2*pi*radius*radius*slices;
}

/**
