/**
 * Write a function to find if the given number is deficient or not.
 * > checkDeficient(12)
 * false
 * > checkDeficient(15)
 * true
 * > checkDeficient(18)
 * false
 */
bool checkDeficient(int n) {
	int sum = 0;
	for (int i = 1; i < n; i++) {
		if (n % i == 0) {
			sum += i;
		}
	}
	return sum < n;
}

/**
 * Write a function to find if the given number is perfect or not.
 * > checkPerfect(6)
 * true
 * > checkPerfect(7)
 * false
 * > checkPerfect(28)
 * true
 */
bool checkPerfect(int n) {
	int sum = 0;
	for (int i = 1; i < n; i++) {
		if (n % i == 0) {
			sum += i;
		}
	}
	return sum == n;
}

/**
 * Write a function to find if the given number is abundant, deficient or perfect or not.
 * > classifyNumber(12)
 * abundant
 * > classifyNumber(15)
 * deficient
 * > classifyNumber(18)
 * perfect
 * > classifyNumber(496)
 * abundant
 * > classifyNumber(8128)
 * perfect
 */
string classifyNumber(int n) {
	string response = "";
	if (checkAbundant(n)) {
		response += "abundant";
	}
	if (checkDeficient(n)) {
		response += "deficient";
	}
	if (checkPerfect(n)) {
		response += "perfect";
	}
	return response;
}

