 * both
 * > classifyArray([1, 8, 85, 86])
 * odd
 */
string classifyArray(vector<int> arr) {
	string response = "";
	bool even = false;
	bool odd = false;
	for (int i = 0; i < arr.size(); i++) {
		if (arr[i] % 2 == 0) {
			even = true;
		}
		else {
			odd = true;
		}
	}
	if (even && odd) {
		response += "both";
	}
	else if (even) {
		response += "even";
	}
	else if (odd) {
		response += "odd";
	}
	return response;
}

