 * True
 * > allInOrder("aabcd", "aacdb")
 * False
 * > allInOrder("aabcd", "aacdb", 4)
 * True
 * > allInOrder("aabcd", "aacdb", 5)
 * False
 */
bool allInOrder(string str1, string str2, int start = 0) {
	if(str1.size() == 0 && str2.size() == 0)
		return true;
	if(str1.size() == 0 || str2.size() == 0)
		return false;
	char s1 = str1[0];
	char s2 = str2[start];
	str1.erase(str1.begin());
	str2.erase(str2.begin() + start);
	if(s1 == s2)
		return allInOrder(str1, str2, 0);
	else
		return allInOrder(str1, str2, start + 1);
}

