/**
 * Write a function to calculate the mean value of the given data.
 * > meanCalc(vector<int>{4, 2, 5, 8, 6})
 * 4.6
 * > meanCalc(vector<int>{1, 2, 3, 4, 5, 6, 7})
 * 4.0
 * > meanCalc(vector<int>{5, 9, 10, 15, 6, 4})
 * 8.6
 */
double meanCalc(vector<int> data) {
	int sum = 0;
	for (int i : data)
		sum += i;
	return 1.0 * sum / data.size();
}

