 */
int countFullYears(int y1, int y2) {
	int count1 = 0;
	while (y1 <= y2) {
		y1 += 1;
		count1++;
	}
	return count1;
}

/**
 * Write a function to count the number of full months between the given dates.
 * > countFullMonths(2020, 8, 2020, 8)
 * 0
 * > countFullMonths(2020, 8, 2020, 9)
 * 1
 * > countFullMonths(2020, 8, 2020, 10)
 * 2
 * > countFullMonths(2020, 8, 2021, 8)
 * 12
 * > countFullMonths(2020, 8, 2021, 9)
 * 1
 */
int countFullMonths(int y1, int m1, int y2, int m2) {
	int count1 = 0;
	while (y1 <= y2) {
		y1 += 1;
		count1++;
	}
	count1 -= 1;
	count1 *= 12;
	count1 += m1;
	count1 -= 1;
	count1 += m2;
	return count1;
}

/**
 * Write a function to count the number of days between the given dates.
 * > countFullDays(2020, 8, 1, 2020, 8, 1)
 * 0
 * > countFullDays(2020, 8, 1, 2020, 8, 2)
 * 1
 * > countFullDays(2020, 8, 1, 2020, 9, 1)
 * 31
 * > countFullDays(2020, 8, 1, 2021, 8, 1)
 * 365
 * > countFullDays(2020, 8, 1, 2021, 9, 1)
 * 396
 */
int countFullDays(int y1, int m1, int d1, int y2, int m2, int d2) {
	int count1 = 0;
	while (y1 <= y2) {
		y1 += 1;
		count1++;
	}
	count1 -= 1;
	count1 *= 365;
	count1 += countMonthNumber(y1, m1);
	count1 -= d1;
	count1 += countMonthNumber(y2, m2);
	count1 -= d2;
	return count1;
}

