	pq.push(1); // push 1 in heap
	map<int, int> visited; // keep track of the visited number and the prime it is mapped to, since we need that to compare the new generated number with other numbers that are less than this number and use that to update next number to be the multiples of the prime mapped to that

	while(n) {
		int currentNum = pq.top(); // current number, i.e. the element in the top of the priority_queue
		pq.pop(); // remove that element
		n--; // decrement count of the numbers needed
		for(auto& num : primes) { // traverse through the prime list
			int newNum = currentNum * num; // new generated number, i.e. the element in the priority_queue times the prime mapped to that
			if(visited.find(newNum) == visited.end()) { // if this number has not been pushed to the priority_queue then push it to the priority_queue
				pq.push(newNum);
				visited[newNum] = num;
			}
		}
	}
	return currentNum; // return the element in the top of the priority_queue
}

