 * > count2("aabcdcbaa", "cb")
 * 2
 * > count2("a", "cb")
 * 0
 * > count2("anurag", "ur")
 * 2
 */
int count2(string s, string x) {
	int count = 0;
	string::size_type last = s.find(x);
	while (last != string::npos) {
		count++;
