	string out;
	string tmp;
	for (char c : text) {
		if (isupper(c)) {
			tmp += (' ' + c);
		} else {
			tmp += c;
		}
	}
	string::iterator iter = tmp.begin();
	while(iter != tmp.end()) {
		char c = *iter;
		if (c == '_' or c == '-') {
			while(c == '_' or c == '-') {
				iter++;
